import{_ as o,a0 as p,w as s,s as i,I as n,x as e,a1 as l,A as r,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"英特尔 Optane：用于数据中心内存缓存 | LCTT x X-CMD","titleTemplate":false,"description":"英特尔 Optane：用于数据中心内存缓存 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"英特尔 Optane：用于数据中心内存缓存 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"英特尔 Optane：用于数据中心内存缓存 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190404 Intel formally launches Optane for data center memory caching","title":"英特尔 Optane：用于数据中心内存缓存","tag":"202102","desc":""},"relativePath":"202102/20190404 Intel formally launches Optane for data center memory caching.md","filePath":"[post].md"}'),d={name:"202102/20190404 Intel formally launches Optane for data center memory caching.md"};function u(f,t,D,O,w,g){const a=p("Link");return s(),i("div",null,[t[24]||(t[24]=n("h1",{id:"英特尔-optane-用于数据中心内存缓存",tabindex:"-1"},[e("英特尔 Optane：用于数据中心内存缓存 "),n("a",{class:"header-anchor",href:"#英特尔-optane-用于数据中心内存缓存","aria-label":"Permalink to “英特尔 Optane：用于数据中心内存缓存”"},"​")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/12/111720yq1rvxcncjdsjb0g.jpg",alt:""})],-1)),t[26]||(t[26]=n("blockquote",null,[n("p",null,"英特尔推出了包含 3D Xpoint 内存技术的 Optane 持久内存产品线。英特尔的这个解决方案介乎于 DRAM 和 NAND 中间，以此来提升性能。")],-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://images.idgesg.net/images/article/2018/06/intel-optane-persistent-memory-100760427-large.jpg",alt:"Intel"})],-1)),n("p",null,[t[1]||(t[1]=e("英特尔在 2019 年 4 月的",-1)),l(a,{href:"https://www.networkworld.com/article/3386142/intel-unveils-an-epic-response-to-amds-server-push.html"},{default:r(()=>[...t[0]||(t[0]=[e("大规模数据中心活动",-1)])]),_:1}),t[2]||(t[2]=e("中正式推出 Optane 持久内存产品线。它已经问世了一段时间，但是目前的 Xeon 服务器处理器还不能充分利用它。而新的 Xeon8200 和 9200 系列可以充分利用 Optane 持久内存的优势。",-1))]),t[28]||(t[28]=n("p",null,"由于 Optane 是英特尔的产品（与美光合作开发），所以意味着 AMD 和 ARM 的服务器处理器不能够支持它。",-1)),n("p",null,[t[4]||(t[4]=e("正如",-1)),l(a,{href:"https://www.networkworld.com/article/3279271/intel-launches-optane-the-go-between-for-memory-and-storage.html"},{default:r(()=>[...t[3]||(t[3]=[e("我之前所说的",-1)])]),_:1}),t[5]||(t[5]=e("，OptaneDC 持久内存采用与美光合作研发的 3D Xpoint 内存技术。3D Xpoint 是一种比 SSD 更快的非易失性内存，速度几乎与 DRAM 相近，而且它具有 NAND 闪存的持久性。",-1))]),n("p",null,[t[7]||(t[7]=e("第一个 3D Xpoint 产品是被称为英特尔“尺子”的 SSD，因为它们被设计成细长的样子，很像尺子的形状。它们被设计这样是为了适合 1u 的服务器机架。在发布的公告中，英特尔推出了新的利用四芯或者 QLC 3D NAND 内存的英特尔 SSD D5-P4325 ",-1)),l(a,{href:"https://www.theregister.co.uk/2018/02/02/ruler_and_miniruler_ssd_formats_look_to_banish_diskstyle_drives/"},{default:r(()=>[...t[6]||(t[6]=[e("尺子",-1)])]),_:1}),t[8]||(t[8]=e(" SSD，可以在 1U 的服务器机架上放 1PB 的存储。",-1))]),t[29]||(t[29]=m('<p>OptaneDC 持久内存的可用容量最初可以通过使用 128GB 的 DIMM 达到 512GB。英特尔数据中心集团执行副总裁及总经理 Navin Shenoy 说：“OptaneDC 持久内存可达到的容量是 DRAM 的 2 到 4 倍。”</p><p>他说：“我们希望服务器系统的容量可以扩展到每个插槽 4.5TB 或者 8 个插槽 36TB，这是我们第一代 Xeon 可扩展芯片的 3 倍。”</p><h3 id="英特尔optane内存的使用和速度" tabindex="-1">英特尔Optane内存的使用和速度 <a class="header-anchor" href="#英特尔optane内存的使用和速度" aria-label="Permalink to “英特尔Optane内存的使用和速度”">​</a></h3><p>Optane 有两种不同的运行模式：内存模式和应用直连模式。内存模式是将 DRAM 放在 Optane 内存之上，将 DRAM 作为 Optane 内存的缓存。应用直连模式是将 DRAM 和 OptaneDC 持久内存一起作为内存来最大化总容量。并不是每个工作负载都适合这种配置，所以应该在对延迟不敏感的应用程序中使用。正如英特尔推广的那样，Optane 的主要使用情景是内存模式。</p><p>几年前，当 3D Xpoint 最初发布时，英特尔宣称 Optane 的速度是 NAND 的 1000 倍，耐用是 NAND 的 1000 倍，密度潜力是 DRAM 的 10 倍。这虽然有点夸张，但这些因素确实很令人着迷。</p><p>在 256B 的连续 4 个缓存行中使用 Optane 内存可以达到 8.3GB/秒的读速度和 3.0GB/秒的写速度。与 SATA SSD 的 500MB/秒左右的读/写速度相比，可以看到性能有很大提升。请记住，Optane 充当内存，所以它会缓存被频繁访问的 SSD 中的内容。</p><p>这是了解 OptaneDC 的关键。它能将非常大的数据集存储在离内存非常近的位置，因此具有很低延迟的 CPU 可以最小化访问较慢的存储子系统的访问延迟，无论存储是 SSD 还是 HDD。现在，它提供了一种可能性，即把多个 TB 的数据放在非常接近 CPU 的地方，以实现更快的访问。</p><h3 id="optane-内存的一个挑战" tabindex="-1">Optane 内存的一个挑战 <a class="header-anchor" href="#optane-内存的一个挑战" aria-label="Permalink to “Optane 内存的一个挑战”">​</a></h3><p>唯一真正的挑战是 Optane 插进内存所在的 DIMM 插槽。现在有些主板的每个 CPU 有多达 16 个 DIMM 插槽，但是这仍然是客户和设备制造商之间需要平衡的电路板空间：Optane 还是内存。有一些 Optane 驱动采用了 PCIe 接口进行连接，可以减轻主板上内存的拥挤。</p><p>3D Xpoint 由于它写数据的方式，提供了比传统的 NAND 闪存更高的耐用性。英特尔承诺 Optane 提供 5 年保修期，而很多 SSD 只提供 3 年保修期。</p><hr>',11)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),l(a,{href:"https://www.networkworld.com/article/3387117/intel-formally-launches-optane-for-data-center-memory-caching.html#tk.rss_all"},{default:r(()=>[...t[9]||(t[9]=[e("https://www.networkworld.com/article/3387117/intel-formally-launches-optane-for-data-center-memory-caching.html#tk.rss_all",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=e("作者：",-1)),l(a,{href:"https://www.networkworld.com/author/Andy-Patrizio/"},{default:r(()=>[...t[11]||(t[11]=[e("Andy Patrizio",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),l(a,{href:"https://github.com/ShuyRoy"},{default:r(()=>[...t[13]||(t[13]=[e("RiaXu",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),l(a,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const y=o(d,[["render",u]]);export{S as __pageData,y as default};
